p.write_text('''def transform(grid):
    h, w = len(grid), len(grid[0])
    wall = next(c for c in range(w) if all(row[c] == 4 for row in grid))
    out = [[0] * 7 for _ in range(h)]
    # The marker is the starting point of the colored path.
    r0 = c0 = 0
    for r, row in enumerate(grid):
        for c in range(wall + 1, len(row)):
            if row[c] == 5:
                r0, c0 = r, c - wall - 1
    out[r0][c0] = 5

    # The 3x3 glyphs encode path segments: A=right 3, B=left 2,
    # C=down 2, D=left 4. Read the tile field column-major.
    rules = {
        ((0,0),(0,1),(1,0),(1,2),(2,1)): ("h", 3, 1),
        ((0,0),(0,2),(1,0),(1,2),(2,0),(2,1),(2,2)): ("h", 2, -1),
        ((0,0),(0,2),(1,1),(2,1)): ("v", 2, 0),
        ((0,0),(0,1),(0,2),(1,1),(2,0),(2,2)): ("h", 4, -1),
    }
    tiles = []
    for left in (0, 4):
        for top in range(0, h, 4):
            if top + 2 >= h or left + 2 >= wall:
                continue
            colors = sorted({grid[y][x] for y in range(top, top + 3)
                             for x in range(left, left + 3)
                             if grid[y][x] not in (0, 4)})
            for color in colors:
                pts = [(y - top, x - left)
                       for y in range(top, top + 3)
                       for x in range(left, left + 3)
                       if grid[y][x] == color]
                minr = min(y for y, x in pts)
                minc = min(x for y, x in pts)
                shape = tuple(sorted((y - minr, x - minc) for y, x in pts))
                if shape in rules:
                    kind, length, direction = rules[shape]
                    tiles.append((color, kind, length, direction))

    y, x = r0, c0
    for color, kind, length, direction in tiles:
        y += 1
        if kind == "h":
            for i in range(length):
                xx = x + direction * i
                if 0 <= y < h and 0 <= xx < 7:
                    out[y][xx] = color
            x += direction * (length - 1)
        else:
            for i in range(length):
                yy = y + i
                if 0 <= yy < h and 0 <= x < 7:
                    out[yy][x] = color
            y += length - 1
    return out
''')
